import{z as E,x as A,o as r,c as B,q as o,j as t,D as n,d as l,s as i,S as p,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"背包 FPTAS","description":"","frontmatter":{"title":"背包 FPTAS","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/knapsack-fptas.md","filePath":"cs/knapsack-fptas.md","lastUpdated":1791063341000}'),P={name:"cs/knapsack-fptas.md"};function d(m,a,T,v,S,f){const s=A("Mermaid");return r(),B("div",null,[a[2]||(a[2]=o('<h1 id="背包-fptas" tabindex="-1">背包 FPTAS <a class="header-anchor" href="#背包-fptas" aria-label="Permalink to &quot;背包 FPTAS&quot;">​</a></h1><div class="epigraph"><p>0-1 背包伪多项式 $O(nW)$ 或 $O(nV)$；按价值缩放丢掉低位，$(1-\\varepsilon)$ 近似且时间 $\\mathrm{poly}(n,1/\\varepsilon)$。</p><footer>—— 据 Ibarra and Kim, Fast Approximation Algorithms for the Knapsack and Sum of Subset Problems, 1975；CLRS 第 35.5 节；[背包](/cs/knapsack) 整理</footer></div><p>上一课<a href="/cs/lp-rounding">LP 舍入</a>依赖解的间隙结构；背包更幸运，有 FPTAS：对任意 \\(\\varepsilon\\)，运行时间多项式于 \\(n\\) 与 \\(1/\\varepsilon\\)。主干背包 DP \\(\\Theta(nW)\\) 的麻烦在 \\(W\\) 大时它不是输入规模的多项式——\\(W\\) 在输入里只占 \\(\\log W\\) 位。缺口是缩放：把大数值压小，同时控制住误差。本课不重写 0-1 转移；后课局部搜索转向最大割。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>价值 \\(v_i\\)，容量 \\(W\\)，DP 可按容量也可按价值展开。FPTAS 令 \\(K=\\varepsilon v_{\\max}/n\\)，把每个价值 \\(v_i\\) 换成 \\(\\lfloor v_i/K\\rfloor\\)，对缩放后的价值做 DP，容量约束仍精确检查。相对误差 \\(\\le\\varepsilon\\)，时间 \\(O(n^3/\\varepsilon)\\) 量级（随实现而变）。</p><p>缺口是缩放，不是贪性价比——按单位重量价值贪心没有近似比保证，构造一组「一件超贵重物加一堆恰好塞满的低价值物」就能让它差到任意倍。</p><h3 id="不是所有-npc-都有-fptas" tabindex="-1">不是所有 NPC 都有 FPTAS <a class="header-anchor" href="#不是所有-npc-都有-fptas" aria-label="Permalink to &quot;不是所有 NPC 都有 FPTAS&quot;">​</a></h3><p>强 NPC 问题（三维匹配等）若再有 FPTAS 就推出 P=NP；背包只是弱 NPC——难点在数值大而非组合结构本身，伪多项式时间存在，所以常有 FPTAS 跟进。</p><p><span class="marginnote">Ibarra–Kim 1975。CLRS 35.5。后课最大割局部搜索 2-近似/期望。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>四步：找 \\(v_{\\max}\\) 定出缩放因子 \\(K\\)；把每个 \\(v_i\\) 换成 \\(\\lfloor v_i/K\\rfloor\\)；对缩放价值做 DP，状态值域压到 \\(O(n^2/\\varepsilon)\\)；沿 DP 表回代还原选品。</p>',11)),(r(),t(p,null,{default:n(()=>[i(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20V%5B%22%E4%BB%B7%E5%80%BC%20v_i%22%5D%20--%3E%20SC%5B%22%E9%99%A4%20K%20%E5%8F%96%E6%95%B4%22%5D%0A%20%20SC%20--%3E%20DP%5B%22%E4%BB%B7%E5%80%BC%20DP%22%5D%0A%20%20DP%20--%3E%20EPS%5B%22(1-%CE%B5)%20%E8%BF%91%E4%BC%BC%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"完全背包与分数背包本就更容易，点名即可：分数背包按密度贪心即最优，完全背包的 DP 也不需要缩放技巧。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[l("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"误差账这样算：每个物品的舍入误差 \\(\\lt K\\)，至多 \\(n\\) 件，总误差 \\(\\lt nK=\\varepsilon v_{\\max}\\le\\varepsilon\\,\\mathrm{OPT}\\)（末步用 OPT \\(\\ge v_{\\max}\\)：最优解至少装得下单件最贵物）。容量约束从未放松，解总是可行。与伪多项式的关系是关键：\\(O(nW)\\) 的毛病是 \\(W\\) 可指数于输入位数，缩放后状态值域只随 \\(n^2/\\varepsilon\\) 长，才真正多项式。与 PTAS 的差别在时间表：FPTAS 要求 \\(n\\) 与 \\(1/\\varepsilon\\) 双双多项式，PTAS 允许 \\(n^{f(1/\\varepsilon)}\\) 这种在 \\(1/\\varepsilon\\) 上指数的表。",-1)),a[6]||(a[6]=e("p",null,"那张不等式链就是保证的全部来源；这张图把它串成一条线，回答「凭什么敢丢低位」。",-1)),(r(),t(p,null,{default:n(()=>[i(s,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20R1%5B%22%E4%B8%80%E4%BB%B6%E7%89%A9%E5%93%81%E8%88%8D%E5%85%A5%E8%AF%AF%E5%B7%AE%20lt%20K%22%5D%20--%3E%20R2%5B%22%E8%87%B3%E5%A4%9A%20n%20%E4%BB%B6%EF%BC%8C%E7%B4%AF%E8%AE%A1%20lt%20nK%22%5D%0A%20%20R2%20--%3E%20R3%5B%22%E5%8F%96%20K%20%3D%20%CE%B5%C2%B7v_max%2Fn%3Cbr%3E%E6%80%BB%E8%AF%AF%E5%B7%AE%20lt%20%CE%B5%C2%B7v_max%22%5D%0A%20%20R3%20--%3E%20R4%5B%22OPT%20%E8%87%B3%E5%B0%91%E8%A3%85%E5%BE%97%E4%B8%8B%E6%9C%80%E8%B4%B5%E5%8D%95%E4%BB%B6%3Cbr%3EOPT%20ge%20v_max%22%5D%0A%20%20R4%20--%3E%20R5%5B%22%E7%BB%93%E8%AE%BA%EF%BC%9A%E8%AF%AF%E5%B7%AE%20lt%20%CE%B5%C2%B7OPT%22%5D%0A%20%20R5%20--%3E%20OK%5B%22%E8%A7%A3%E4%BB%8D%E5%8F%AF%E8%A1%8C%EF%BC%9A%E5%AE%B9%E9%87%8F%E5%85%A8%E7%A8%8B%E7%B2%BE%E7%A1%AE%E6%A3%80%E6%9F%A5%22%5D%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=o('<p><span class="marginnote">数字实例：\\(n=100\\) 件、\\(v_{\\max}=10^6\\)、\\(\\varepsilon=0.1\\) 时 \\(K=10^3\\)；价值 123456 记成 123，零头 456 被丢掉。DP 状态值域从百万级压到约 \\(n^2/\\varepsilon=10^5\\) 级，而总误差不超过 \\(\\varepsilon\\cdot v_{\\max}=10^5\\)——「只记到千元位」换来十倍以上的状态压缩。</span></p><p><span class="marginnote">直觉类比：缩放就是换记账单位——原来精确到分，现在只记到千元；每笔账最多差一个不足千元的零头，一百笔账的零头加起来也不过十万，相对「总盘子」是个可控的小比例。FPTAS 的全部艺术在于把零头总和钉死在 \\(\\varepsilon\\) 倍最优解以内。</span></p><p><span class="marginnote">术语翻译：FPTAS 全称「完全多项式时间近似方案」，拆开读：近似方案=对每个精度要求 \\(\\varepsilon\\) 给一套算法；多项式时间=耗时同时多项式于输入规模 \\(n\\) 和 \\(1/\\varepsilon\\)；完全（F）=连 \\(1/\\varepsilon\\) 也不能出现在指数上——这是它比 PTAS「更体面」的那一档。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写多维背包——两维以上即是强 NPC，FPTAS 随之丧失（除非 P=NP）。不写 EPTAS。后课默认：0-1 背包有 FPTAS。下一课局部搜索与最大割。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>缩放价值 + DP = FPTAS。</li><li>弱 NPC 才有此路。</li><li>贪心性价比不是 FPTAS。</li><li>出处：Ibarra and Kim, 1975；CLRS 第 35.5 节。</li></ul>',7))])}const C=E(P,[["render",d]]);export{_ as __pageData,C as default};
